import fs from 'node:fs';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { dbFile, homeDir, schemaFile } from '../paths.js';

                              

function pragmas(db              , busyMs        )       {
  db.exec(`PRAGMA journal_mode = WAL; PRAGMA synchronous = NORMAL; PRAGMA busy_timeout = ${busyMs}; PRAGMA foreign_keys = ON; PRAGMA secure_delete = ON;`);
}

export function openCoreDb()               {
  fs.mkdirSync(homeDir(), { recursive: true });
  const db = new DatabaseSync(dbFile());
  pragmas(db, 200);
  const v = (db.prepare('PRAGMA user_version').get()                            ).user_version;
  if (v === 0) {
    db.exec('BEGIN');
    try {
      db.exec(fs.readFileSync(schemaFile, 'utf8'));
      db.prepare("INSERT OR REPLACE INTO meta (key, value) VALUES ('schema_version', '2')").run();
      db.exec('COMMIT');
    } catch (e) {
      db.exec('ROLLBACK');
      throw e;
    }
  } else if (v === 1) {
    migrateToV2(db);
  } else if (v !== 2) {
    throw new Error(`troop.db schema version ${v} is not supported`);
  }
  db.exec('CREATE INDEX IF NOT EXISTS usage_session_idx ON usage (session_id)');
  allowSandbox(db);
  if (!(db.prepare('PRAGMA table_info(session)').all()                           ).some((c) => c.name === 'driven_engine')) db.exec('ALTER TABLE session ADD COLUMN driven_engine TEXT');
  if (!(db.prepare('PRAGMA table_info(session)').all()                           ).some((c) => c.name === 'parent_id')) db.exec('ALTER TABLE session ADD COLUMN parent_id TEXT REFERENCES session(id)');
  db.exec('CREATE INDEX IF NOT EXISTS event_kind_idx ON event (kind, seq)');
  if (!(db.prepare('PRAGMA table_info(run)').all()                           ).some((c) => c.name === 'hidden')) db.exec('ALTER TABLE run ADD COLUMN hidden INTEGER NOT NULL DEFAULT 0');
  const gateCols = (db.prepare('PRAGMA table_info(gate)').all()                           ).map((c) => c.name);
  if (!gateCols.includes('scan')) db.exec('ALTER TABLE gate ADD COLUMN scan TEXT');
  if (!gateCols.includes('override_reason')) db.exec('ALTER TABLE gate ADD COLUMN override_reason TEXT');
  if (!(db.prepare('PRAGMA table_info(needs_you)').all()                           ).some((c) => c.name === 'notified_at')) db.exec('ALTER TABLE needs_you ADD COLUMN notified_at TEXT');
  const schemaText = fs.readFileSync(schemaFile, 'utf8');
  for (const table of ['notify_sink', 'notify_delivery']) db.exec(schemaBlock(schemaText, new RegExp(`CREATE TABLE ${table} \\([\\s\\S]*?\\n\\);`, 'g'))[0].replace('CREATE TABLE', 'CREATE TABLE IF NOT EXISTS'));
  return db;
}

const V2_TABLES = ['session', 'event', 'comment', 'needs_you'];
const V1_DROPPED = ['window_name', 'herdr_pane', 'herdr_at'];

function schemaBlock(schema        , re        )           {
  return [...schema.matchAll(re)].map((m) => m[0]);
}

/** Recreates table `t` from its schema.sql definition, copying every old column through `select`; old columns schema.sql lacks are added back without constraints unless named in `drop`. */
function rebuildTable(db              , schema        , t        , select                          = (c) => c, drop           = [])       {
  const create = schemaBlock(schema, new RegExp(`CREATE TABLE ${t} \\([\\s\\S]*?\\n\\);`, 'g'))[0];
  db.exec(create.replace(`CREATE TABLE ${t} (`, `CREATE TABLE ${t}_v2 (`));
  const fresh = new Set((db.prepare(`PRAGMA table_info(${t}_v2)`).all()                           ).map((c) => c.name));
  const old = db.prepare(`PRAGMA table_info(${t})`).all()                                         ;
  for (const c of old.filter((o) => !fresh.has(o.name) && !drop.includes(o.name))) {
    try {
      db.exec(`ALTER TABLE ${t}_v2 ADD COLUMN "${c.name.replace(/"/g, '""')}" ${c.type}`);
    } catch (e) {
      const used = db.prepare(`SELECT 1 FROM ${t} WHERE "${c.name.replace(/"/g, '""')}" IS NOT NULL LIMIT 1`).get();
      if (used) throw new Error(`troop.db: rebuilding ${t} would lose column ${c.name}, which holds data (${(e         ).message})`);
    }
  }
  const cols = (db.prepare(`PRAGMA table_info(${t}_v2)`).all()                           ).map((c) => c.name);
  const oldNames = new Set(old.map((c) => c.name));
  const keep = cols.filter((c) => oldNames.has(c)).map((c) => (/^\w+$/.test(c) ? c : `"${c.replace(/"/g, '""')}"`));
  db.exec(`INSERT INTO ${t}_v2 (${keep.join(', ')}) SELECT ${keep.map(select).join(', ')} FROM ${t}`);
  db.exec(`DROP TABLE ${t}`);
  db.exec(`ALTER TABLE ${t}_v2 RENAME TO ${t}`);
  for (const idx of schemaBlock(schema, new RegExp(`CREATE INDEX \\w+\\s+ON ${t} \\([^)]*\\);`, 'g'))) db.exec(idx);
}

/** Rebuilds session, comment, needs_you and plugin once when their CHECKs predate a host or kind schema.sql now allows. */
export function allowSandbox(db              )       {
  const sql = (t        ) => (db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = ?").get(t)                               )?.sql ?? '';
  const stale = [['session', "'external'"], ['comment', "'notice'"], ['needs_you', "'uncommitted'"], ['plugin', "'registry-import'"]].filter(([t, v]) => sql(t) && !sql(t).includes(v)).map(([t]) => t);
  if (!stale.length) return;
  const schema = fs.readFileSync(schemaFile, 'utf8');
  db.exec('PRAGMA foreign_keys = OFF');
  db.exec('BEGIN IMMEDIATE');
  try {
    for (const t of stale) rebuildTable(db, schema, t);
    if ((db.prepare('PRAGMA foreign_key_check').all()             ).length) throw new Error('foreign key check failed after rebuild');
    db.exec('COMMIT');
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  } finally {
    db.exec('PRAGMA foreign_keys = ON');
  }
}

/** Version 1 to 2: in-app terminals. Rebuilds the four tables whose CHECKs or columns changed, in one transaction. */
export function migrateToV2(db              )       {
  const schema = fs.readFileSync(schemaFile, 'utf8');
  db.exec('PRAGMA foreign_keys = OFF');
  db.exec('BEGIN IMMEDIATE');
  try {
    for (const t of V2_TABLES) {
      rebuildTable(db, schema, t, (c) => (t === 'session' && c === 'host' ? "'pty'" : t === 'event' && c === 'source' ? "CASE WHEN source IN ('claude-hook','launch','codex-notify') THEN source ELSE 'core' END" : c), V1_DROPPED);
    }
    db.exec(schemaBlock(schema, /CREATE TABLE ui_selection \([\s\S]*?\n\);/g)[0]);
    if ((db.prepare('PRAGMA foreign_key_check').all()             ).length) throw new Error('foreign key check failed after migration');
    db.prepare("INSERT OR REPLACE INTO meta (key, value) VALUES ('schema_version', '2')").run();
    db.exec('PRAGMA user_version = 2');
    db.exec('COMMIT');
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  } finally {
    db.exec('PRAGMA foreign_keys = ON');
  }
}

export function openReaderDb()                      {
  const file = dbFile();
  if (!fs.existsSync(file)) return null;
  return new DatabaseSync(file, { readOnly: true });
}

export function tx   (db              , fn         )    {
  db.exec('BEGIN IMMEDIATE');
  try {
    const r = fn();
    db.exec('COMMIT');
    return r;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

export function ensureDir(p        )       {
  fs.mkdirSync(path.dirname(p), { recursive: true });
}
